{
  "course_basic_info": {
    "course_name": "Advanced Algorithms",
    "topic": "Dynamic Programming",
    "target_audience": "Third-year undergraduate students majoring in Computer Science related majors",
    "total_class_duration": "90 minutes"
  },
  "teaching_objectives": {
    "knowledge_objectives": [
      "Master the core idea and two fundamental properties of dynamic programming (DP): overlapping subproblems and optimal substructure",
      "Clarify the differences and connections between DP, divide-and-conquer algorithm and greedy algorithm",
      "Master the general design steps of DP, and master the modeling method of classic DP problems (0-1 knapsack, longest common subsequence)"
    ],
    "ability_objectives": [
      "Can abstract reasonable DP state and derive correct state transition equations for common complex optimization problems",
      "Can analyze the time and space complexity of DP algorithms, and master basic DP optimization techniques",
      "Can implement DP algorithms to solve practical engineering and programming problems"
    ],
    "quality_objectives": [
      "Cultivate problem decomposition thinking and computational thinking for dealing with complex problems",
      "Cultivate the awareness of balancing algorithm time and space overhead, improve systematic problem-solving literacy"
    ]
  },
  "key_points": [
    "Core idea and essential properties of dynamic programming",
    "General design steps of dynamic programming algorithms",
    "Modeling and solution of classic dynamic programming problems"
  ],
  "difficulties": [
    "How to abstract reasonable state and derive correct state transition equations for unknown problems",
    "Distinguishing the applicable scenarios of DP, greedy and divide-and-conquer",
    "Space-time optimization techniques for dynamic programming"
  ],
  "pre_class_preparation": [
    "Review the knowledge of divide-and-conquer and greedy algorithms learned earlier",
    "Pre-read the basic concept of dynamic programming, and try to think about the solution of the minimum path sum problem of digital triangle in advance"
  ],
  "classroom_activity_design": [
    {
      "activity_name": "Warm-up: Problem-induced Introduction",
      "duration": "10 minutes",
      "content": "1. Present the classic minimum path sum problem of digital triangle: Given a triangle formed by numbers, find the minimum sum of paths from the top to the bottom, each step can only move to the adjacent number in the next row. 2. Ask students to analyze the efficiency of brute force and divide-and-conquer solutions, guide students to find that a large number of subproblems are calculated repeatedly, leading to extremely low efficiency. 3. Raise the core question: How to avoid repeated calculation of overlapping subproblems? Introduce the theme of the class - dynamic programming"
    },
    {
      "activity_name": "Concept Construction: Core Properties of DP",
      "duration": "20 minutes",
      "content": "1. Combine the digital triangle problem to explain the core idea of DP: store the answers of solved subproblems to avoid repeated calculation. 2. Formalize two essential properties: overlapping subproblems (the same subproblem is solved multiple times in recursive decomposition) and optimal substructure (the optimal solution of the original problem contains the optimal solution of subproblems). 3. Compare DP with divide-and-conquer (divide-and-conquer subproblems are independent, DP subproblems overlap) and greedy (greedy makes local optimal choice without guaranteeing global optimal, DP obtains global optimal through state transition), sort out the applicable scenarios of different algorithms. 4. Summarize the general 5-step design process of DP: characterize optimal structure → define state → derive state transition → calculate optimal value → construct optimal solution"
    },
    {
      "activity_name": "Case Demonstration: 0-1 Knapsack Problem Solution",
      "duration": "25 minutes",
      "content": "1. Give the problem description of 0-1 knapsack: Given n items with weight w[i] and value v[i], and a knapsack with capacity W, select items to maximize the total value without exceeding the capacity. 2. Guide students to think independently: ask students to try to define DP state, call on students to share their ideas, then formalize dp[i][j] as the maximum value obtained by considering the first i items and the knapsack capacity is j. 3. Derive the state transition equation together, fill the DP table with a small specific example, let students see the calculation process intuitively. 4. Guide students to think about space optimization: explain that each row of the DP table only depends on the previous row, so rolling array can be used to reduce space complexity from O(nW) to O(W), demonstrate the optimized calculation process"
    },
    {
      "activity_name": "Group Discussion: LCS Problem Modeling",
      "duration": "25 minutes",
      "content": "1. Divide students into groups of 3-4 people, give the Longest Common Subsequence (LCS) problem: given two strings, find the length of the longest common subsequence. 2. Assign group tasks: ① Define reasonable DP state; ② Write state transition equation; ③ Calculate the result of the example: s1 = \"abcde\", s2 = \"ace\". 3. After 15 minutes of discussion, invite 2 groups to present their results, comment and correct, sort out the standard solution of LCS"
    },
    {
      "activity_name": "Summary Q&A & Extended Thinking",
      "duration": "10 minutes",
      "content": "1. Sort out the core knowledge points of the class, emphasize that the core of DP modeling is correct state definition. 2. Answer students' questions raised in the learning and discussion process. 3. Put forward extended thinking: how to construct the actual LCS sequence instead of only getting the length? Briefly introduce common DP variants (interval DP, tree DP, state compression DP) for subsequent learning"
    }
  ],
  "after_class_assignment": [
    "Basic task: Implement 0-1 knapsack and LCS algorithm with space optimization, and submit the executable code",
    "Improved task: Solve the longest palindromic subsequence problem using DP, analyze its time and space complexity",
    "Extended thinking: Try to compare the difference between top-down memoization search and bottom-up DP, and summarize their respective applicable scenarios"
  ]
}

