{
  "course_basic_info": {
    "course_name": "Operating Systems",
    "teaching_topic": "Concurrency and Parallelism",
    "target_audience": "Sophomore undergraduate students majoring in Computer Science",
    "class_duration": "50 minutes"
  },
  "teaching_objectives": [
    {
      "objective_type": "Knowledge Objective",
      "content": "1. Master the core definitions of concurrency and parallelism in the context of operating systems; 2. Clearly distinguish the essential differences between the two concepts; 3. Recognize the application scenarios of concurrency and parallelism in modern computer systems; 4. Understand the role of the operating system in managing concurrent and parallel tasks"
    },
    {
      "objective_type": "Ability Objective",
      "content": "1. Can correctly classify actual system task scenarios into concurrency, parallelism, or both; 2. Can explain the efficiency advantage of concurrency on single-core processors; 3. Can analyze the design logic of common systems (such as web servers, multi-tasking desktops) combined with the two concepts"
    },
    {
      "objective_type": "Quality Objective",
      "content": "1. Cultivate the thinking of abstracting computer principles from daily phenomena; 2. Establish awareness of system resource optimization and parallel program design; 3. Stimulate interest in exploring the working mechanism of operating systems"
    }
  ],
  "key_points_and_difficulties": {
    "key_points": [
      "Definitions of concurrency and parallelism",
      "Essential differences between concurrency and parallelism",
      "Typical application scenarios of the two concepts in operating systems"
    ],
    "difficulties": [
      "Understanding the difference between logical overlapping of tasks (concurrency) and physical simultaneous execution (parallelism)",
      "Understanding why concurrency improves system efficiency even on single-core processors",
      "Distinguishing scenarios where concurrency and parallelism coexist in modern multi-core systems"
    ]
  },
  "pre_class_preparation": [
    "Students preview the basic knowledge of process scheduling from the previous chapter",
    "Teacher prepares interactive scenario materials and animation demos of OS task scheduling"
  ],
  "classroom_activity_design": [
    {
      "activity_name": "Warm-up: Daily Phenomenon Group Discussion",
      "duration": "10 minutes",
      "process": "1. Divide students into groups of 3-4; 2. Propose discussion questions: If you need to make boiled water and fried eggs for breakfast, what are two different ways to finish the two tasks? What is the essential difference between the two ways? 3. Invite 2 groups to share conclusions, then lead in: the two methods correspond to the core concepts of this class: concurrency and parallelism"
    },
    {
      "activity_name": "Interactive Sorting: Concept Distinguishing Exercise",
      "duration": "15 minutes",
      "process": "1. Distribute 6 task scenarios to each group: (1) Single-core CPU running browser and WeChat at the same time; (2) 8-core CPU rendering 8 3D frames at the same time; (3) Web server handling 2000 user requests at the same time on 16 cores; (4) Single-threaded Node.js handling multiple user I/O requests; (5) A person switches back and forth between answering work messages and watching online lectures; (6) Large AI model trained simultaneously across 16 GPUs; 2. Groups sort the scenarios into 3 categories: only concurrency, only parallelism, both concurrency and parallelism (5 minutes for discussion); 3. Explain each scenario one by one, correct common misunderstandings (e.g. \"concurrency requires multiple cores\", \"single thread cannot support concurrency\"), and summarize the core difference: concurrency is logically simultaneous, focusing on improving resource utilization through task switching; parallelism is physically simultaneous, focusing on accelerating task completion with multiple hardware resources"
    },
    {
      "activity_name": "Case Deep Dive: Why Can Single-Threaded Node.js Handle High Concurrency?",
      "duration": "15 minutes",
      "process": "1. Propose the engineering question: Node.js uses a single thread to handle requests, why can it support thousands of concurrent user requests better than multi-threaded schemes in I/O-intensive scenarios? 2. Groups discuss for 7 minutes, give explanations combined with new concepts; 3. Guide the analysis: When a request waits for I/O (e.g. reading database), Node.js and the OS switch to process another request, which is concurrency: tasks overlap in time dimension, do not need to run physically at the same time, greatly improving CPU utilization; 4. Play the scheduling demo animation: compare concurrent task scheduling on single-core and concurrent + parallel scheduling on multi-core to visualize the difference"
    },
    {
      "activity_name": "Summary and Homework Assignment",
      "duration": "10 minutes",
      "process": "1. Sort out the knowledge framework: definition → difference → application → OS support; 2. Answer students' questions; 3. Assign homework: Find 2 concurrency examples and 2 parallelism examples in daily computer use, and write a 100-word explanation for each; Think about what problems concurrency will bring to OS management (preparation for next class on thread synchronization)"
    }
  ],
  "after_class_assessment": [
    "Check homework to judge students' mastery of concept distinction",
    "Add 2-3 concept test questions in the unit exam to assess mastery",
    "Collect common misunderstandings for supplementary explanation in review classes"
  ]
}

