{
  "Teaching Material": {
    "Prerequisite Knowledge": "Basic characteristics of market structures, definition of oligopoly, introductory game theory terms (strategy, payoff, dominant strategy)",
    "Teaching Duration": "50 minutes (for undergraduate intermediate microeconomics course)",
    "Teaching Objectives": {
      "Knowledge Objectives": [
        "Master the definition of Nash Equilibrium in the context of oligopolistic markets",
        "Explain how Nash Equilibrium applies to price and output competition among oligopoly firms",
        "Understand why collusive agreements (explicit or tacit) between oligopolies are inherently unstable"
      ],
      "Ability Objectives": [
        "Able to construct 2×2 payoff matrices for simple oligopoly strategic games",
        "Able to identify Nash Equilibrium using the best-response method for one-shot oligopoly games",
        "Able to use Nash Equilibrium logic to analyze real-world phenomena such as price wars and OPEC quota violations"
      ],
      "Core Literacy Objectives": [
        "Cultivate strategic thinking for analyzing interactions between independent decision-makers",
        "Recognize the tension between individual rationality and collective rationality in market competition",
        "Develop the ability to connect economic theory to real business and public policy scenarios"
      ]
    },
    "Key and Difficult Points": {
      "Key Points": [
        "Core connotation of Nash Equilibrium: a self-enforcing strategy profile where no player can improve their payoff by changing strategy unilaterally",
        "The prisoner's dilemma of oligopoly collusion explained by Nash Equilibrium",
        "Method for identifying Nash Equilibrium in 2×2 oligopoly games"
      ],
      "Difficult Points": [
        "Distinguishing between dominant strategy equilibrium and general Nash Equilibrium",
        "Understanding that Nash Equilibrium is self-enforcing but does not guarantee maximum collective profit for oligopolies",
        "Extending one-shot game Nash Equilibrium logic to repeated oligopoly interactions in real markets"
      ]
    },
    "Classroom Activity Design": {
      "Activity Name": "Duopoly Price War Simulation",
      "Activity Objective": "Help students intuitively experience the formation of Nash Equilibrium and the instability of collusion in oligopolistic markets",
      "Required Materials": "Printed strategy decision cards, whiteboard, projection",
      "Procedure": [
        {
          "Step": "1. Grouping and Context Introduction (5 mins)",
          "Description": "Split the class into two equal groups: Firm A (Coke) and Firm B (Pepsi), two duopolists in the cola market. Explain the setup: both firms can choose to set a high collusive price ($5 per 2L bottle) or undercut to a low price ($3 per 2L). The activity runs in two rounds."
        },
        {
          "Step": "2. First Round: One-Shot Game (10 mins)",
          "Description": "Each student individually decides their strategy (High Price / Low Price) and writes it on the decision card, no communication with the opposite group allowed. Match each Firm A student with a random Firm B student, calculate payoffs per the pre-set rule: Both High = $10M profit each; One High One Low = Low price firm gets $15M, High price firm gets $2M; Both Low = $5M profit each. Count and announce the outcome distribution to the class."
        },
        {
          "Step": "3. Second Round: Collusive Negotiation Round (10 mins)",
          "Description": "Allow 3 minutes for representatives of the two groups to publicly negotiate an agreement to both set High Price to maximize total profit. After negotiation, each student again secretly writes down their strategy, repeat matching and outcome counting. Most students will still choose Low Price despite the collusive agreement."
        },
        {
          "Step": "4. Guided Debrief and Knowledge Summary (15 mins)",
          "Description": "1. Draw the payoff matrix on the board, use the best-response method to prove that (Low Price, Low Price) is the dominant strategy Nash Equilibrium. 2. Explain the core logic: this outcome is a classic prisoner's dilemma for oligopolies, where individual rationality leads to a collectively suboptimal result, which is why collusion tends to break down. 3. Extend to repeated games: Ask \"If we played this game 10 times in a row, would the outcome change?\" Guide students to conclude that repeated interaction can support collusive outcomes as a Nash Equilibrium when credible punishment for cheating exists."
        }
      ],
      "Post-Activity Discussion Questions": [
        "Use Nash Equilibrium theory to explain why OPEC members frequently exceed their agreed production quotas",
        "Is the Nash Equilibrium of a price competition oligopoly game always bad for consumers? Explain your answer"
      ]
    },
    "After-Class Assessment": [
