{
  "course_basic_info": {
    "course_name": "Intermediate Microeconomics",
    "knowledge_point": "General Equilibrium Theory",
    "target_audience": "Sophomore undergraduate students majoring in Economics/Finance",
    "class_duration": "90 minutes"
  },
  "teaching_objectives": {
    "knowledge_objectives": [
      "Distinguish the core differences between partial equilibrium analysis and general equilibrium analysis",
      "Master the definition and economic implication of Walras' Law",
      "Understand the core assumptions, existence conclusion and First/Second Welfare Theorems of the Arrow-Debreu general equilibrium framework"
    ],
    "ability_objectives": [
      "Can identify the interdependence across different markets and apply general equilibrium thinking to analyze the impact of external shocks or economic policies",
      "Can reasonably select between partial and general equilibrium analysis according to different research scenarios"
    ],
    "quality_objectives": [
      "Cultivate systematic economic thinking instead of one-sided partial analysis",
      "Establish a rigorous understanding of the logical foundation of market efficiency theory, and recognize the application premises and limitations of general equilibrium theory"
    ]
  },
  "key_points_and_difficulties": {
    "key_points": [
      "Contrast between partial equilibrium and general equilibrium analysis paradigms",
      "Walras' Law and its economic intuition",
      "Core conclusions and welfare implications of Arrow-Debreu general equilibrium theory"
    ],
    "difficult_points": [
      "Intuitive understanding of the existence proof of general equilibrium",
      "Distinguishing between positive description and normative judgment of general equilibrium outcomes",
      "Applying general equilibrium thinking to solve real-world economic problems, rather than only mastering abstract theoretical concepts"
    ]
  },
  "classroom_activity_design": [
    {
      "activity_name": "Warm-up: Shock Spillover Brainstorm",
      "duration": "15 minutes",
      "process": [
        "Divide students into groups of 4 people, give the scenario: The government imposes a 30% consumption tax on fossil energy. Please list all possible spillover effects to other markets within 5 minutes",
        "Invite 2 groups to share their results, then instructor guides students to summarize: Partial equilibrium analysis only focuses on the change of the fossil energy market itself, while general equilibrium analysis captures the full impact of the shock across all interconnected markets",
        "Introduce the core definition of general equilibrium: A state where all markets in the economy are simultaneously in equilibrium, with no excess demand or excess supply in any market"
      ]
    },
    {
      "activity_name": "Interactive Demonstration: Walras' Law Experiment",
      "duration": "20 minutes",
      "process": [
        "Invite 3 volunteers to act as 3 different markets: grain market, clothing market, labor market",
        "Rule: The sum of all 3 markets' excess demand (demand minus supply) in a closed economy must equal 0, which follows Walras' law",
        "First round: 2 volunteers write +2 (excess demand) and 0 on their cards, ask the whole class to guess the third market's excess demand, then verify with the third volunteer's card (it is -2, excess supply)",
        "Second round: 2 volunteers write 0 for their excess demand, ask the class what the third must be (0), then summarize the core implication of Walras' law: For an economy with n markets, if n-1 markets are in equilibrium, the nth market must also be in equilibrium"
      ]
    },
    {
      "activity_name": "Mini Debate: Which Analysis Should We Use for Minimum Wage Hike?",
      "duration": "25 minutes",
      "process": [
        "Divide the remaining class into two groups: Pro side (general equilibrium analysis is necessary for minimum wage policy evaluation), Con side (partial equilibrium analysis is sufficient)",
        "Give 8 minutes for group preparation, then 12 minutes for open debate (3 minutes opening for each side, 6 minutes cross debate, 1.5 minutes closing for each side)",
        "Instructor summary: General equilibrium captures full effects such as higher labor costs pushing up output prices, employment spillover to uncovered sectors, which partial equilibrium misses, but partial equilibrium is simpler and sufficient when the affected sector is very small. The choice of method depends on the specific research question"
      ]
    }
  ],
  "after_class_arrangement": {
    "required_assignment": "Read the case study of the impact of 1970s oil price shocks on the US economy, write a 300-word short answer explaining how general equilibrium analysis captures the full effect that partial equilibrium misses",
    "extended_reading": "Excerpts from Walras' *Elements of Pure Economics* and Arrow's seminal paper on general equilibrium existence for interested students"
  }
}

{
  "course_basic_info": {
    "course_name": "Intermediate Microeconomics",
    "target_audience": "Sophomore Undergraduate Students in Economics",
    "class_duration": "45 minutes"
  },
  "teaching_objectives": {
    "knowledge_objectives": [
      "Master the definition and core assumptions of non-cooperative games",
      "Grasp the concept of Nash Equilibrium and its core logic of 'no unilateral incentive to deviate'",
      "Master the best response method to identify pure-strategy Nash Equilibrium in 2-player normal-form games"
    ],
    "ability_objectives": [
      "Distinguish between dominant strategy equilibrium and general Nash Equilibrium correctly",
      "Apply the Nash Equilibrium framework to analyze common real-world strategic interaction problems"
    ],
    "value_objectives": [
      "Cultivate rational strategic thinking for interactive decision-making scenarios",
      "Understand the conflict between individual rationality and collective rationality in non-cooperative games, and recognize the role of institutional design in improving social welfare"
    ]
  },
  "key_points_and_difficulties": {
    "key_points": [
      "Core attributes of non-cooperative games (no binding cooperative agreements between players, decision-making based on individual rationality)",
      "Concept and core logic of Nash Equilibrium",
      "Method for identifying pure-strategy Nash Equilibrium"
    ],
    "difficulties": [
      "Understanding the 'no player can improve payoff via unilateral deviation' principle",
      "Clarifying the difference and connection between dominant strategy equilibrium and Nash Equilibrium",
      "Applying Nash Equilibrium theory to explain and predict outcomes of real-world strategic interactions"
    ]
  },
  "classroom_activity_design": [
    {
      "activity_name": "Warm-up: Prisoner's Dilemma Role Play",
      "duration": "10 minutes",
      "procedure": [
        "Divide all students into random pairs, assign the role of Prisoner A/B to each, explain rules: no communication between pairs (no binding agreement, fits non-cooperative game definition), publicize the payoff matrix: both confess → 5 years in prison each; both silent → 1 year each; one confess one silent → confessor gets 0 years, silent gets 8 years",
        "Ask students to make independent decisions, then count the distribution of outcomes across all pairs",
        "Raise the guiding question 'Why do most pairs end up with both confessing, even though both staying silent gives a better outcome for both?' to introduce core concepts"
      ]
    },
    {
      "activity_name": "Concept Lecture + Interactive Check",
      "duration": "15 minutes",
      "procedure": [
        "Define non-cooperative games: games where no enforceable agreement exists between players, all players make decisions to maximize their own payoff",
        "Define Nash Equilibrium formally: 'A strategy profile where no player can increase their own payoff by unilaterally changing their strategy, holding all other players' strategies constant', explain the core logic of mutual best response and no deviation incentive",
        "Connect to the warm-up: confirm (Confess, Confess) is the Nash Equilibrium of Prisoner's Dilemma",
        "Teach the best response marking method to find Nash Equilibrium, practice with a 2x2 price competition game, clarify that all dominant strategy equilibria are Nash Equilibria but not vice versa (use left/right driving coordination game as an example)"
      ]
    },
    {
      "activity_name": "Group Inquiry: Real Case Analysis",
      "duration": "15 minutes",
      "procedure": [
        "Divide students into 3 groups, assign each a real case: 1) Why do OPEC members often exceed agreed production quotas? 2) Why do price wars between chain supermarkets always hurt both sides? 3) What is the Nash Equilibrium of individual vaccination decisions without government mandate during an epidemic?",
        "Give 8 minutes for group discussion, require groups to draw the payoff matrix and identify the Nash Equilibrium",
        "Each group sends a representative to present analysis (2 minutes per group), instructor gives timely feedback and correction"
      ]
    },
    {
      "activity_name": "Summary and Q&A",
      "duration": "5 minutes",
      "procedure": [
        "Summarize core points: Nash Equilibrium is a stable outcome of non-cooperative games where no player has incentive to change choice unilaterally, and it often deviates from the optimal collective outcome",
        "Answer student questions and assign after-class tasks"
      ]
    }
  ],
  "after_class_assignment": [
    "Identify all pure-strategy Nash Equilibria in the given 'Chicken Game' payoff matrix",
    "Write a 300-word short analysis of the Nash Equilibrium of cross-country carbon emission reduction in non-cooperative scenarios"
  ]
}

