  "teaching_objectives": [
    {
      "type": "Knowledge Objective",
      "content": "Master the definition of market failure; master the two core characteristics of public goods (non-rivalry, non-excludability); understand the mechanism of how public goods trigger market failure through the free rider problem; be able to distinguish public goods, private goods, common-pool resources and club goods"
    },
    {
      "type": "Ability Objective",
      "content": "Be able to apply the theory of market failure and public goods to analyze real economic phenomena; cultivate problem-solving ability through simulation and case discussion; be able to propose reasonable solutions to the problem of insufficient public goods supply"
    },
    {
      "type": "Quality Objective",
      "content": "Establish a correct cognition of the relationship between market mechanism and government intervention; cultivate public awareness and social responsibility; form a rigorous economic thinking mode for analyzing public affairs"
    }
  ],
  "key_and_difficult_points": {
    "key_points": [
      "Definition and connotation of market failure",
      "Two core characteristics of public goods",
      "Free rider problem and the mechanism of public goods causing market failure",
      "Common solutions to market failure caused by public goods"
    ],
    "difficult_points": [
      "Correctly classify different types of goods based on the two dimensions of rivalry and excludability",
      "Understand the logic that individual rational choice leads to collective irrational outcome in public goods provision",
      "Balance the roles of market and government in public goods provision under different contexts"
    ]
  },
  "classroom_activity_design": [
    {
      "activity_stage": "Lead-in: Case Question Trigger",
      "duration": "5 minutes",
      "teacher_activity": "Show pictures of a public lighthouse and a private commercial coffee shop, ask the core guiding question: 'Both are public-facing facilities. Why are most coffee shops built and operated by private enterprises in a free market, while almost all lighthouses are invested by the government?' Collect preliminary answers from students and trigger thinking",
      "student_activity": "Share initial opinions freely, generate learning interest and confusion about the question"
    },
    {
      "activity_stage": "Core Concept Explanation & Interactive Check",
      "duration": "12 minutes",
      "teacher_activity": "1. Explain the definition of market failure: the situation where the free market cannot achieve efficient resource allocation, resulting in social welfare loss; 2. Introduce two classification dimensions of goods: rivalry (one's consumption reduces consumption available to others) and excludability (can prevent non-payers from using the good); 3. Draw a 2*2 matrix of four types of goods, define public goods as non-rival and non-excludable goods; 4. Explain the free rider problem: non-payers cannot be excluded from enjoying public goods, so consumers have incentive to free ride without payment, leading to private producers unable to recover costs, thus forming market failure; 5. Ask interactive questions (e.g. 'Is street lighting a public good? Why?') to check mastery",
      "student_activity": "Take notes, answer interactive questions, initially grasp core concepts"
    },
    {
      "activity_stage": "Core Simulation: Free Rider Game",
      "duration": "18 minutes",
      "teacher_activity": "1. Divide students into groups of 5, distribute 10 virtual tokens per person, explain rules: 'Each can contribute 0-10 tokens to the group public good fund. The total contribution will be doubled and evenly split among all 5 members regardless of personal contribution; uncontributed tokens are personal income, goal is to maximize personal income'; 2. Organize 2 rounds of the game, collect total contribution data of each group; 3. Debrief: Guide students to compare the socially optimal outcome (all contribute 10, each gets 20 tokens) and actual outcome (most groups have far lower total contribution, most individuals contribute 0 or very little), connect the game result to real market failure; 4. Ask follow-up question 'What if we can exclude non-contributors? Will the result change?' to guide deep thinking",
      "student_activity": "Participate in the game, count personal income, share group results, participate in discussion, and intuitively experience the logic of free rider problem"
    },
    {
      "activity_stage": "Case Expansion & Class Summary",
      "duration": "10 minutes",
      "teacher_activity": "1. Show real cases (national defense, urban park, toll highway, streaming membership) and ask students to classify them; 2. Summarize solutions: government public provision financed by tax is the main solution for pure public goods, quasi-public goods can adopt private provision with government regulation; 3. Conclude the core point: Public goods are an important cause of market failure, the market mechanism is not omnipotent, and appropriate government intervention can improve social welfare",
      "student_activity": "Participate in classification discussion, sort out the knowledge system of this lesson"
    }
  ],
  "after_class_arrangement": {
    "assignment": "Select a public goods provided by your local government, analyze why it cannot be effectively supplied by the private market, and write a 300-word short analysis",
    "extended_thinking": "Search for the case of private lighthouses in British history, think: under what conditions can the private market supply public goods?"
  }
}

