{
  "course_basic_info": {
    "course_name": "Introduction to Common Law System",
    "target_audience": "First-year undergraduate law students",
    "teaching_duration": "45 minutes"
  },
  "teaching_objectives": [
    "Knowledge Objective: Master the core definition and historical origin of the Doctrine of Precedent (stare decisis), distinguish between binding precedent and persuasive precedent, and understand the foundational role of court hierarchy in the operation of the doctrine",
    "Ability Objective: Be able to accurately distinguish ratio decidendi (binding legal reasoning) from obiter dicta (non-binding side comments) in judicial decisions, and can analyze the application of precedent in simple typical common law cases",
    "Quality Objective: Cultivate critical thinking on the value of the common law system, understand the balance between legal stability and judicial flexibility, and form an objective cognition of the differences between common law and civil law systems"
  ],
  "key_points": [
    "Core concept: The meaning of the Latin maxim stare decisis et non quieta movere (stand by decided matters, do not disturb what is settled)",
    "Classification of precedent: Clear boundaries between binding precedent and persuasive precedent",
    "Operational foundation: The decisive role of court hierarchy in determining whether a precedent is binding"
  ],
  "teaching_difficulties": [
    "Accurately identifying ratio decidendi and obiter dicta in actual judicial judgments",
    "Understanding the inherent flexibility of the doctrine, avoiding the misunderstanding that precedent completely rigidifies judicial decision-making, and grasping the mechanisms of distinguishing, overruling and reversing precedents"
  ],
  "pre_class_preparation": [
    "Assign pre-class reading: Simplified legal excerpt of the landmark common law case *Donoghue v Stevenson (1932)*",
    "Prepare teaching PPT, case analysis handouts for group activities, and interactive discussion boards for online/offline teaching"
  ],
  "classroom_activity_design": [
    {
      "segment": "Warm-up & Topic Introduction (5 minutes)",
      "content": "Teacher raises a guiding question: 'If a similar dispute was judged by a court 20 years ago, must today's judge follow that old judgment? What are the pros and cons of this rule?' Invite 2-3 students to share ideas, then introduce that this core rule of common law is exactly the Doctrine of Precedent to be learned in this class."
    },
    {
      "segment": "Core Concept Lecturing (15 minutes)",
      "content": "1. Explain origin and core logic: The doctrine formed from the development of English customary law, the core requirement is that courts must follow legal rules established by previous decisions in similar cases to maintain legal predictability. 2. Clarify basic classifications: Distinguish binding precedent (must be followed, derived from higher courts in the same judicial jurisdiction) and persuasive precedent (can be referred to but not required to be followed, derived from lower courts, other jurisdictions, and non-core comments of judges). 3. Explain key sub-concepts: Clearly distinguish ratio decidendi (the binding legal principle that forms the basis of the judgment) and obiter dicta (non-binding comments on legal issues not directly related to the current dispute). 4. Introduce flexibility mechanisms: Judges can 'distinguish' the current case from the old precedent by finding factual differences, and higher courts can overrule wrong outdated precedents, so the doctrine is not a rigid rule."
    },
    {
      "segment": "Group Case Analysis Challenge (15 minutes)",
      "content": "1. Divide students into groups of 4, each group gets a simplified handout of *Donoghue v Stevenson* with key paragraphs of the judgment marked. 2. Assign group tasks: (1) Mark which part of the judgment is ratio decidendi and which part is obiter dicta; (2) Explain why Lord Atkin's 'neighbor principle' became a binding precedent for all subsequent negligence cases; (3) Discuss one advantage and one disadvantage of the Doctrine of Precedent. 3. Groups discuss and sort out conclusions within the time limit."
    },
    {
      "segment": "Presentation & Teacher Debrief (7 minutes)",
      "content": "Invite 1-2 groups to present their conclusions, then the teacher debriefs: Correct common mistakes (such as confusing obiter dicta with case facts, misjudging the binding force of precedent), and emphasizes that the core value of the doctrine is balancing the predictability of law and the adaptability of law to social change."
    },
    {
      "segment": "Summary & Homework (3 minutes)",
      "content": "Recap the core logic of the doctrine: court hierarchy determines binding force, ratio decidendi is the core of precedent, the doctrine balances stability and flexibility. Assign homework: Write a 300-word short reflection comparing the Doctrine of Precedent in common law with the application of guiding cases in civil law systems, to be submitted before the next class."
    }
  ],
  "assessment_suggestion": "Formative assessment accounts for 40% (based on classroom group activity participation and discussion performance), and summative assessment accounts for 60% (based on post-class homework and final case analysis tests, focusing on testing the ability to distinguish core concepts and apply the doctrine to analyze actual cases)"
}

