{
  "course_basic_info": {
    "course_name": "Public Administration Theory",
    "target_audience": "Third-year undergraduate students majoring in Public Administration",
    "class_duration": "90 minutes"
  },
  "teaching_objectives": {
    "knowledge_objectives": [
      "Master the core connotation and multiple dimensions of bureaucratic accountability",
      "Grasp the evolution context, core arguments and basic assumptions of four mainstream theories of bureaucratic accountability",
      "Understand the new development of bureaucratic accountability theory in the digital governance era"
    ],
    "ability_objectives": [
      "Can compare and evaluate the advantages, disadvantages and adaptability of different theories",
      "Can apply relevant theoretical tools to analyze real-world accountability problems in public governance",
      "Can form independent critical thinking on the reform of bureaucratic accountability system"
    ],
    "quality_objectives": [
      "Cultivate public service values and a correct understanding of public administrators' responsibility",
      "Establish the awareness that bureaucratic accountability is the core guarantee of good governance and public interest"
    ]
  },
  "key_points_and_difficulties": {
    "key_points": [
      "Core concept and multidimensional division of bureaucratic accountability",
      "Core arguments, theoretical background and value orientation of main theories of bureaucratic accountability",
      "Practical implications of different theories for the construction of accountability system"
    ],
    "difficulties": [
      "Evaluating the contextual adaptability of different theories, avoiding one-sided worship of a single theory",
      "Applying theoretical frameworks to analyze complex real-world accountability dilemmas",
      "Understanding the new changes of bureaucratic accountability in the context of multi-stakeholder governance and digital transformation"
    ]
  },
  "teaching_content": [
    {
      "section": "1. Core Concept of Bureaucratic Accountability",
      "content": "Bureaucratic accountability refers to the institutional mechanism that public bureaucrats need to explain their decisions and behaviors to relevant stakeholders, accept supervision, and bear corresponding consequences (including rewards and punishments). Sort out four core dimensions: internal accountability vs external accountability, political accountability vs administrative accountability, vertical accountability vs horizontal accountability, individual accountability vs collective accountability."
    },
    {
      "section": "2. Evolution and Core Arguments of Main Theories",
      "content": "1. Traditional Democratic Accountability Theory (early 20th century, Wilson, Weber): Core view: Bureaucracy is accountable to elected political officials, who are in turn accountable to the public; relies on hierarchical internal control and parliamentary oversight to ensure political responsiveness. Strength: guarantees the unification of political authority; Weakness: easy to cause rigid bureaucracy and low efficiency. 2. New Public Management (NPM) Accountability Theory (1980s, Osborne, Gaebler): Born in the wave of global public sector reform, core view: Build results-oriented accountability, requires bureaucracy to be accountable to 'service customers' and parliaments, introduces market competition and performance evaluation to improve accountability efficiency. Strength: improves administrative efficiency; Weakness: easily erodes public value, leads to accountability fragmentation. 3. New Public Service (NPS) Accountability Theory (1990s, Denhardt): A theoretical critique of NPM, core view: Bureaucracy should be accountable to citizens and the overall public interest, not just customers; emphasizes the combination of democratic accountability, professional accountability and legal accountability, prioritizes public value over economic benefits. Strength: reorients accountability to public interest; Weakness: difficult to operationalize in practice. 4. Network Governance Accountability Theory (after 2000): Adapted to the trend of multi-center governance, core view: Public services are provided through cooperation of government, market and social organizations, so bureaucracy needs to bear multiple accountabilities to multiple stakeholders, emphasizes interactive, horizontal accountability beyond traditional hierarchy."
    },
    {
      "section": "3. Contemporary New Development",
      "content": "Briefly introduce new topics such as algorithmic accountability and open government accountability emerging in the digital governance era, and how new technologies reshape the practice of bureaucratic accountability."
    }
  ],
  "classroom_activity_design": [
    {
      "activity_name": "Warm-up: Case Lead-in",
      "duration": "10 minutes",
      "process": "Teacher presents a real public governance case: 'A city government approved the construction of a waste incineration plant near a residential area without full public consultation, which triggered mass protests. Finally the project was suspended, and the main persons in charge of relevant departments were held accountable.' Teacher raises guiding questions: 'Which subjects should the municipal bureaucracy be accountable to in this case? What is the core problem of accountability in this event?' Invite 2-3 students to share views, then introduce the course topic."
    },
    {
      "activity_name": "Group Discussion: Theoretical Analysis of Case",
      "duration": "20 minutes",
      "process": "Divide the whole class into 4 groups, each group is assigned one of the four theories of bureaucratic accountability. Group tasks: 1. From the perspective of the assigned theory, what are the main accountability problems in the waste incineration case? 2. What improvement suggestions will your theory put forward? Groups discuss internally and select a representative to prepare for presentation."
    },
    {
      "activity_name": "Group Presentation & Interactive Q&A",
      "duration": "35 minutes",
      "process": "Each group representative gives a 5-minute presentation, after each presentation, 2 minutes are reserved for other groups to ask questions or put forward different views. The teacher sorts out the core differences between different theories on PPT during the interaction."
    },
    {
      "activity_name": "Summary & Sublimation",
      "duration": "15 minutes",
      "process": "The teacher summarizes the core differences of the four theories from three dimensions: 'who to be accountable to', 'how to hold accountable', 'what is the goal of accountability', points out that no theory is one-size-fits-all, and the construction of accountability system needs to adapt to specific governance context, guides students to think about how to absorb the advantages of various theories to improve China's bureaucratic accountability system."
    },
    {
      "activity_name": "After-class Assignment",
      "duration": "After class",
      "process": "Require students to select a typical bureaucratic accountability case announced in the past two years, analyze the case with two different theories, write a 1000-1500 word analysis paper, which accounts for 10% of the course's usual score."
    }
  ],
  "key_references": [
    "Rosenbloom D H. Public Administration: Understanding Management, Politics, and Law in the Public Sector",
    "Romzek B S, Dubnick M J. Accountability in the public sector: Lessons from the Challenger tragedy",
    "Zhang Chengfu. Evolution and enlightenment of bureaucratic accountability theory, Chinese Public Administration"
  ]
}

