      {
        "step": "Step 3: Presentation and debrief (9 minutes)",
        "content": "2 groups present their conclusion for each case (1.5 minutes per group, 6 minutes total), followed by 2 minutes peer interaction, then 1 minute instructor summary to correct misconceptions, emphasize that ~30% of adverse drug reactions are related to common genetic variants, pharmacogenomics has been integrated into routine clinical practice"
      }
    ]
  },
  "post_class_arrangement": [
    "Search the latest CPIC guideline for a pharmacogenomic biomarker of your choice, write a 300-word reflection on how it improves patient outcomes",
    "Prepare for the next class debate topic: Should routine pharmacogenomic testing be mandatory before most prescription drugs?"
  ],
  "assessment_method": [
    "Classroom participation (20%)",
    "Post-class reflection assignment (30%)",
    "Final exam (50%)"
  ]
}

