    {
      "stage": "Group Presentation & Peer Interaction",
      "duration": "30 minutes",
      "content": [
        "Each group gives a 5-minute presentation, followed by 2 minutes of peer Q&A",
        "Peers score the presentation from the dimensions of mechanism matching, clinical rationality and innovation of strategy"
      ]
    },
