{
  "teaching_material": {
    "course_basic_info": {
      "course": "Social Psychology",
      "target_learner": "Undergraduate students (freshman/sophomore)",
      "total_class_time": "45 minutes"
    },
    "teaching_objectives": [
      {
        "type": "knowledge_objective",
        "content": "1. Master the core definition and origin of Cognitive Dissonance Theory proposed by Leon Festinger; 2. Grasp the three common strategies people use to reduce cognitive dissonance; 3. Understand the core assumptions of the theory and its common application scenarios."
      },
      {
        "type": "ability_objective",
        "content": "1. Can accurately identify cognitive dissonance phenomena in daily life and distinguish it from other similar cognitive biases; 2. Can apply Cognitive Dissonance Theory to analyze real social phenomena such as attitude polarization, consumption behavior and public health behavior."
      },
      {
        "type": "emotional_value_objective",
        "content": "1. Guide students to reflect on their own cognitive dissonance and irrational decision-making tendencies; 2. Cultivate the awareness of adjusting cognition rationally when facing contradictory information."
      }
    ],
    "key_points": [
      "Core definition and basic assumptions of Cognitive Dissonance Theory",
      "Three common cognitive dissonance reduction strategies",
      "Typical application scenarios of Cognitive Dissonance Theory in real life"
    ],
    "difficult_points": [
      "Distinguishing cognitive dissonance from similar cognitive concepts (confirmation bias is often a result of dissonance reduction, not equivalent to dissonance itself)",
      "Predicting and explaining why people choose different dissonance reduction strategies in different contexts",
      "Applying Cognitive Dissonance Theory to design effective interventions for behavior change"
    ],
    "pre_class_preparation": [
      "Students watch a 5-minute introductory clip of Festinger's classic 'When Prophecy Fails' study, and read a 1-page excerpt of the field study case",
      "Students privately record a recent experience of discomfort after making an important decision (such as choosing a major, buying an expensive product) for class discussion"
    ],
    "classroom_activity_design": [
      {
        "activity_name": "Warm-up: Dissonance Experience Sharing",
        "duration": "10 minutes",
        "procedure": [
          "Invite 2-3 volunteers to share their recorded post-decision discomfort experience",
          "Teacher raises guiding questions: 'Why do we keep searching for positive information about the option we chose, and magnify the shortcomings of the option we gave up? Why did the cult in the pre-class study become more devout after their prophecy failed?'",
          "Introduce the origin of Cognitive Dissonance Theory: Leon Festinger's 1957 formal proposal based on the 'When Prophecy Fails' field study"
        ]
      },
      {
        "activity_name": "Core Knowledge Explanation & Concept Clarification",
        "duration": "15 minutes",
        "procedure": [
          "Explain the core definition: Cognitive dissonance is the uncomfortable mental stress caused by an individual holding two or more contradictory cognitions (beliefs, attitudes, or behaviors)",
          "Explain two core assumptions: 1) Individuals have an innate motivation to restore cognitive consistency by reducing dissonance; 2) The intensity of dissonance is proportional to the importance of the involved cognitions",
          "Explain three common dissonance reduction strategies: 1) Change one contradictory cognition (change behavior or belief); 2) Add new consonant cognitions to reconcile the contradiction; 3) Trivialize the contradiction to reduce its perceived importance",
          "Clarify the difference between cognitive dissonance and confirmation bias: Cognitive dissonance is the aversive state that motivates behavior, while confirmation bias (seeking information consistent with existing beliefs) is a common strategy people use to reduce dissonance"
        ]
      },
      {
        "activity_name": "Group Discussion: Dissonance Scenario Challenge",
        "duration": "15 minutes",
        "procedure": [
          "Divide students into groups of 4 people, each group gets a scenario card. The task is to answer 3 questions: 1) What are the two contradictory cognitions that cause dissonance? 2) What are three possible dissonance reduction strategies for this scenario? 3) Which strategy do most people choose in reality, and why?",
          "Scenario examples: ① A student who believes cheating is wrong cheated on the final exam to pass; ② A person who supports climate action bought a gas SUV because it is cheaper than an electric car; ③ A person paid a $500 annual gym membership, but hates going and finds workouts very painful",
          "After 10 minutes of group discussion, each group sends a representative to share their conclusion (1 minute per group)",
          "Teacher summarizes: Points out that the higher the commitment (such as sunk cost of membership money), the more likely people are to adjust their beliefs rather than change behavior to reduce dissonance, and extends the application of the theory in marketing, public health and political science"
        ]
      },
      {
        "activity_name": "Wrap-up & Knowledge Check",
        "duration": "5 minutes",
        "procedure": [
          "Teacher summarizes the core logic of Cognitive Dissonance Theory",
          "Quick check: Ask all students to write one example of cognitive dissonance from their own experience on a small slip of paper and hand it in, to test learning outcome"
        ]
      }
    ],
    "after_class_assignment": [
      "Select a common social phenomenon (such as post-election political polarization, anti-vaccination attitudes, impulse consumption), analyze it with Cognitive Dissonance Theory, and write a 300-word reflection"
    ]
  }
}

