{
  "principle_of_proportionality": {
    "definition": "In constitutional law, the principle of proportionality is a substantive judicial doctrine that requires any state measure which limits or restricts a constitutionally protected fundamental right must be reasonably and narrowly tailored to achieve a legitimate public interest, and may not impose an excessive, unfair burden on individual rights relative to the public benefit the measure delivers.",
    "core standard prongs": [
      "Legitimate Aim: The state must first demonstrate the measure pursues a constitutionally permitted public goal (e.g. public health, national security, equal protection)",
      "Suitability: The measure must have a clear rational connection to actually achieving the stated legitimate aim",
      "Necessity: The state must have chosen the least restrictive alternative means to reach the goal; if a less rights-limiting measure can achieve the same outcome, the original measure fails this prong",
      "Proportionality stricto sensu (balancing): The overall harm to fundamental rights from the measure must not outweigh the public benefit it provides"
    ]
  },
  "application_in_judicial_review": {
    "general purpose": "Courts use proportionality to review the constitutionality of challenged state actions, including legislation, executive orders, administrative rules, and government policies that are alleged to violate fundamental rights",
